import SwiftUI
struct Msg:Identifiable{let id=UUID();let text:String;let mine:Bool}
struct Chat:View{let msgs:[Msg]
  var body:some View{ScrollView{VStack(spacing:6){ForEach(msgs){m in
    HStack{if m.mine{Spacer()};Text(m.text).padding(10).background(m.mine ?Color.blue:Color(.systemGray5)).foregroundColor(m.mine ?.white:.primary).cornerRadius(14);if !m.mine{Spacer()}}}}.padding()}}}
